/**
 * A hit on any line makes the item sensitive (fail closed). Rules are evaluated in order; the
 * first hit sets guard_reason.
 */
export const GuardRule = z.object({
  id: Token,
  reason: GuardReason,
  pattern: z.string().min(1).max(1000),
  ignore_case: z.boolean(),
});
export type GuardRule = z.infer<typeof GuardRule>;

export const GuardRules = z.object({
  rules: z.array(GuardRule).min(1).max(500),
});
export type GuardRules = z.infer<typeof GuardRules>;

/**
 * AI-CHAT heuristic parameters (DESIGN 5.1). >= chat_min_groups signal groups = chat; >=
 * uncertain_min_groups = chat_uncertain (treated as chat); else not_chat.
 */
export const ChatRules = z.object({
  /**
   * Left box starts in the left N of width / right box ends in the right N.
   */
  edge_fraction: z.number().max(0.5).gt(0),
  min_edge_boxes: z.int().min(1),
  min_side_switches: z.int().min(1),
  timestamp_pattern: z.string().min(1).max(1000),
  min_time_marker_lines: z.int().min(1),
  day_header_words: z.array(z.string().min(1).max(64)).max(200),
  name_line_max_words: z.int().min(1),
  min_name_lines: z.int().min(1),
  name_prefix_pattern: z.string().min(1).max(1000),
  messaging_ui_words: z.array(z.string().min(1).max(64)).max(200),
  chat_min_groups: z.int().min(1).max(3),
  uncertain_min_groups: z.int().min(1).max(3),
});
export type ChatRules = z.infer<typeof ChatRules>;

/**
 * AI-GATE high-recall prefilter: any pattern hit on any line = could be actionable.
 */
export const GateRules = z.object({
  patterns: z.array(RulePattern).min(1).max(500),
});
export type GateRules = z.infer<typeof GateRules>;

/**
 * Placeholder type written in place of the match (AI-REDACT).
 */
export const RedactKind = z.enum(["email", "phone", "digits", "otp"]);
export type RedactKind = z.infer<typeof RedactKind>;

export const RedactRule = z.object({
  id: Token,
  kind: RedactKind,
  pattern: z.string().min(1).max(1000),
  ignore_case: z.boolean(),
});
export type RedactRule = z.infer<typeof RedactRule>;

export const RedactRules = z.object({
  rules: z.array(RedactRule).min(1).max(100),
});
export type RedactRules = z.infer<typeof RedactRules>;

/**
 * Purchases (D24): case-insensitive keyword list; any hit sets GuardResult.receipt_like.
 */
export const ReceiptLikeRules = z.object({
  keywords: z.array(z.string().min(1).max(64)).max(200),
});
export type ReceiptLikeRules = z.infer<typeof ReceiptLikeRules>;

/**
 * Purchases (D24): a match on the grounded due evidence line (or the line above) sets
 * deadline_origin = printed_return_by; else other.
 */
export const DeadlineOriginRules = z.object({
  return_phrases: z.array(RulePattern).max(100),
});
export type DeadlineOriginRules = z.infer<typeof DeadlineOriginRules>;

/**
 * Format of shared/rules/rules.json: the single rule set implemented in TS and Kotlin
 * (COMP-RULES: AI-SENSITIVE guard, AI-CHAT heuristic, AI-GATE prefilter, AI-REDACT) plus the
 * purchases receipt_like keywords and deadline_origin return phrases (D24). Regex patterns must
 * stay inside the common subset of ECMAScript and java.util.regex (no lookbehind, no named
 * groups, no inline flags; use ignore_case instead).
 */
export const RulesFile = z.object({
  schema_version: SchemaVersion,
  rules_version: Token,
  guard: GuardRules,
  chat: ChatRules,
  gate: GateRules,
  redact: RedactRules,
  receipt_like: ReceiptLikeRules,
  deadline_origin: DeadlineOriginRules,
});
export type RulesFile = z.infer<typeof RulesFile>;

/**
 * Line bounding box in image pixels (left, top, right, bottom).
 */
export const Box = z.object({
  l: z.int().min(0),
  t: z.int().min(0),
  r: z.int().min(0),
  b: z.int().min(0),
});
export type Box = z.infer<typeof Box>;

export const ImageSize = z.object({
  width: z.int().min(1),
  height: z.int().min(1),
});
export type ImageSize = z.infer<typeof ImageSize>;

export const FixtureLine = z.object({
  t: z.string().max(2000),
  c: Probability,
  box: Box,
});
export type FixtureLine = z.infer<typeof FixtureLine>;

export const RulesExpectation = z.object({
  sensitive: z.boolean(),
  guard_reason: GuardReason.nullable(),
  chat: ChatVerdict,
  actionable: z.boolean(),
  receipt_like: z.boolean(),
  /**
   * Expected redacted text per line, with typed placeholders. Omitted when the case is
   * sensitive (nothing leaves the device).
   */
  redacted_lines: z.array(z.string().max(2000)).optional(),
  deadline_origin: DeadlineOrigin.optional(),
});
export type RulesExpectation = z.infer<typeof RulesExpectation>;

export const RulesCase = z.object({
  id: Token,
  tags: z.array(Token).max(20).optional(),
  image: ImageSize,
  lines: z.array(FixtureLine).max(500),
  expect: RulesExpectation,
});
export type RulesCase = z.infer<typeof RulesCase>;

/**
 * Format of shared/rules/fixtures/*.json: parity cases run against both the TS and the Kotlin
 * rules.json implementations (EVAL-GUARD-PARITY). Synthetic text only; never real screenshot
 * content.
 */
export const RulesFixtureFile = z.object({
  schema_version: SchemaVersion,
  /**
   * rules.json version these expectations were written against.
   */
  rules_version: Token,
  cases: z.array(RulesCase).min(1).max(5000),
});
export type RulesFixtureFile = z.infer<typeof RulesFixtureFile>;

export const Provenance = z.object({
  /**
   * initial = DESIGN 5.5 starting constants (est.); calibrated = fitted by COMP-CALIB on the
   * eval set.
   */
  kind: z.enum(["initial", "calibrated"]),
  /**
   * Repo-relative path of the report attached to the bump commit.
   */
  eval_report: z.string().max(256).optional(),
  seed: z.int().min(0).optional(),
  eval_manifest_sha256: z.string().regex(new RegExp("^[0-9a-f]{64}$")).optional(),
});
export type Provenance = z.infer<typeof Provenance>;

export const VerbalBase = z.object({
  high: Probability,
  medium: Probability,
  low: Probability,
});
export type VerbalBase = z.infer<typeof VerbalBase>;

export const Caps = z.object({
  evidence_fuzzy: Probability,
  ocr_mid: Probability,
  ocr_low: Probability,
  resolve_assumed: Probability,
  resolve_needs_review: Probability,
  validate_failure: Probability,
});
export type Caps = z.infer<typeof Caps>;

export const Bounds = z.object({
  /**
   * Fuzzy evidence match below this clears the field.
   */
  evidence_fuzzy_min: Probability,
  /**
   * OCR line confidence at or above this is uncapped.
   */
  ocr_high_min: Probability,
  /**
   * OCR line confidence below this gets the ocr_low cap.
   */
  ocr_low_max: Probability,
});
export type Bounds = z.infer<typeof Bounds>;

export const StateThresholds = z.object({
  ready_min: Probability,
  ask_min: Probability,
});
export type StateThresholds = z.infer<typeof StateThresholds>;

/**
 * Ask when (1 - p) * c_wrong > c_question.
 */
export const CostRule = z.object({
  c_wrong: z.number().gt(0),
  c_question: z.number().gt(0),
});
export type CostRule = z.infer<typeof CostRule>;

/**
 * Offline pooled Platt fit (report only in the beta; not used at runtime).
 */
export const Calibration = z.object({
  method: z.enum(["platt"]),
  features: z.array(Token).max(64),
  coef: z.array(z.number()).max(64),
  intercept: z.number(),
  ece: z.number().min(0).optional(),
  brier: z.number().min(0).optional(),
});
export type Calibration = z.infer<typeof Calibration>;

/**
 * Format of shared/thresholds/thresholds_vN.json, written by COMP-CALIB and loaded by COMP-GATE
 * (AI-CONF, DESIGN 5.5). Changes only through a human-approved baseline-bump commit with the
 * eval report attached (hard rule 9). Beta user data may only tighten thresholds.
 */
export const ThresholdsFile = z.object({
  schema_version: SchemaVersion,
  /**
   * Matches the file name suffix (v1 for thresholds_v1.json) and travels as
   * ExtractResponse.thresholds_version.
   */
  thresholds_version: z.string().regex(new RegExp("^v[0-9]+$")),
  created_at: IsoDateTime,
  provenance: Provenance,
  verbal_base: VerbalBase,
  caps: Caps,
  bounds: Bounds,
  states: StateThresholds,
  /**
   * An optional field (end, location) scoring below this is cleared to missing and leaves the
   * card score.
   */
  optional_field_min: Probability,
  /**
   * Over-asking alarm: more than this share of cards in Ask triggers a human-reviewed
   * loosening.
   */
  ask_alarm_rate: Probability,
  cost: CostRule,
  calibration: Calibration.optional(),
});
export type ThresholdsFile = z.infer<typeof ThresholdsFile>;

/**
 * Server-internal claims carried on the token record (COMP-AUTH / COMP-QUOTA, D25). tier is
 * server-controlled, defaults to free, and is NEVER read from a client request: ExtractRequest
 * has no tier property, so a client-sent tier is dropped on parse. No billing in the beta;
 * per-tier limits live in COMP-QUOTA config.
 */
export const TokenClaims = z.object({
  tier: Tier.default("free"),
});
export type TokenClaims = z.infer<typeof TokenClaims>;

/**
 * Android only (DESIGN 3.3, D20): the EncryptedSharedPreferences file the app rewrites with a
 * synchronous commit() on every settings change and every app start; read by
 * COMP-ANDROID-WORKER. Excluded from backup and wiped first by delete-all. The worker treats it
 * as missing or stale when the file is absent, format_version differs from the worker's, or
 * app_version differs from the installed app version; then it makes NO network request and
 * writes an inbox entry with status pending_app. Holds the bearer token: never log any value.
 */
export const WorkerConfig = z.object({
  /**
   * Version of this file format. A worker built for another format_version treats the file as
   * stale.
   */
  format_version: z.literal(1),
  app_version: VersionString,
  /**
   * Epoch milliseconds (UTC) of the last rewrite.
   */
  written_at: z.int().min(0),
  /**
   * Opaque bearer token (secret). Never logged, never in kv.
   */
  token: z.string().min(1).max(512),
  server_url: z.string().min(1).max(512).regex(new RegExp("^https?://[^\\s]+$")),
  /**
   * Per-install HMAC salt for idempotency keys (secret to the device).
   */
  install_salt: z.string().min(1).max(256),
  /**
   * Epoch milliseconds (UTC). Screenshots captured before it are never processed automatically.
   */
  install_watermark: z.int().min(0),
  chat_local_only: z.boolean(),
  image_autodetect_opt_in: z.boolean(),
  autodetect_enabled: z.boolean(),
});
export type WorkerConfig = z.infer<typeof WorkerConfig>;

/** Every top-level contract, keyed by its schema file stem (shared/schema/<stem>.schema.json). */
export const schemas = {
  behavior_event: BehaviorEvent,
  error: ErrorResponse,
  extract_request: ExtractRequest,
  extract_response: ExtractResponse,
  guard_result: GuardResult,
  inbox: InboxEntry,
  proposed_action: ProposedAction,
  rules: RulesFile,
  rules_fixture: RulesFixtureFile,
  thresholds: ThresholdsFile,
  token_claims: TokenClaims,
  worker_config: WorkerConfig,
} as const;

export type SchemaName = keyof typeof schemas;
